"""DECLARED NULL: ligand size, ignoring the structure entirely.

Not a published method. Heavy-atom count is the null this task needs rather than a
constant, because within a congeneric series potency correlates with size: measured through
the task's harness on the 13 scored lead-optimisation series it reaches mean r 0.431, above
AutoDock Vina's 0.367. A scoring rule that cannot beat counting atoms has not used the complex.
"""
_FILE = "boltz/mlsb_affinity.py"

_CONTENT = '''
def score_ligands(records, seed=42):
    """Heavy-atom count. Bigger = predicted tighter."""
    return {r["key"]: {"affinity": float(len(r["lig_elem"])),
                       "binder_prob": float(len(r["lig_elem"]))}
            for r in records}
'''

OPS = [
    {
        "op": "replace",
        "file": _FILE,
        "start_line": 46,
        "end_line": 64,
        "content": _CONTENT,
    },
]

"""AutoDock Vina's scoring function, rescoring the co-folded pose.

Reference: Trott & Olson, "AutoDock Vina: improving the speed and accuracy of docking with
a new scoring function...", J. Comput. Chem. 31:455 (2010); computed here by gnina v1.3,
which reports Vina's own `Affinity` term alongside its CNN scores. The value is a predicted
binding free energy in kcal/mol, so lower is tighter and the sign is flipped.
"""
_FILE = "boltz/mlsb_affinity.py"

_CONTENT = '''
def score_ligands(records, seed=42):
    """Vina's empirical score, sign-flipped so higher = tighter."""
    return {r["key"]: {"affinity": -float(r["dock"]["vina"]),
                       "binder_prob": -float(r["dock"]["vina"])}
            for r in records}
'''

OPS = [
    {
        "op": "replace",
        "file": _FILE,
        "start_line": 46,
        "end_line": 64,
        "content": _CONTENT,
    },
]
